beforeExample:
class Example {
    void method(String pattern) {
        String[] parts = pattern.split("\\s*\n\\s*");
    }
}

afterExample:
class Example {
    void method(String pattern) {
        String[] parts = pattern.split("\\s*(?:\\r\\n?|\n)\\s*");
    }
}

negativeExample:
class Example {
    void method(String pattern) {
        // Should not match other split patterns
        String[] parts1 = pattern.split("\t");
        String[] parts2 = pattern.split(" ");
        // Should not match if the string literal is different
        String[] parts3 = pattern.split("\\s*
\\s*");
    }
}
